def powers(z, d):
    from itertools import combinations_with_replacement as cr
    return np.column_stack([np.prod(z[:, i], axis=1) for i in cr(range(z.shape[1]), d)])

def look(a, y):
    e = y - a @ ls(a, y)
    return (np.mean(abs(e)), np.mean(abs(e / (1 - (orth(a) ** 2).sum(1)[:, None]))))

def configs(p, y):
    from scipy.optimize import minimize_scalar
    z = p['u']
    L = []
    F = {'id': lambda z, k: z, 'cube': lambda z, k: z ** 3, 'sinh': lambda z, k: np.sinh(k * z), 'atan': lambda z, k: np.arctan(k * z), 'tanh': lambda z, k: np.tanh(k * z), 'asinh': lambda z, k: np.arcsinh(k * z), 'rat': lambda z, k: z / (1 + k * z * z)}
    E = {'nil': lambda z: np.empty((len(z), 0)), 'lin': lambda z: z, 'sq': lambda z: z * z, 'quad': lambda z: powers(z, 2), 'linsq': lambda z: np.c_[z, z * z], 'lincyc': lambda z: np.c_[z, cyc(z)], 'cyc': cyc, 'lincube': lambda z: np.c_[z, z ** 3]}
    for (fn, f) in F.items():
        for (en, g) in E.items():
            if fn == 'id' and en.startswith('lin'):
                continue

            def d(z, k):
                return np.c_[lin(f(z, k)), g(z)]
            opt = minimize_scalar(lambda k: look(d(z, k), y)[1], bounds=(0.15, 4.0), method='bounded') if fn not in ('id', 'cube') else None
            k = opt.x if opt else 1.0
            a = d(z, k)
            (r, cv) = look(a, y)
            beta = ls(a, y)

            def predict(x, f=f, g=g, k=k, beta=beta):
                return np.c_[lin(f(x, k)), g(x)] @ beta
            L.append((cv, r, fn, en, k, predict, beta))
    L.sort(key=lambda r: r[0])
    print('Panel fit', [(round(cv, 5), round(r, 5), f, g, round(k, 3)) for (cv, r, f, g, k, *_) in L[:12]])
    print(L[0][-1])
    return L

def loo(x, y):
    e = y - x @ ls(x, y)
    h = (np.linalg.qr(x)[0] ** 2).sum(1)
    return np.mean(abs(e / (1 - h[:, None])))
